226			}
227			turns, splitErr := imp.SplitTurns(sf, full)
228			if splitErr != nil {
229				return res, fmt.Errorf("split %s session %s: %w", imp.Name(), sf.SessionID, splitErr)
230			}
231			opts.Progress.sessionStart(sessionIndex, len(files), string(imp.AgentType()), sf.SessionID, len(turns))
