			// (defers are LIFO) — after any bootstrap finalize that creates the
			// GitHub repo and pushes, by which point an origin remote exists.
			defer func() {
				if runErr != nil {
					return
				}
				reportRepoEnabled(ctx, insecureHTTPAuth)
			}()

