			// bootstrap a repo or install any hooks.
			if hasCheckpointBackendFlag(cmd) {
				if _, err := resolveCheckpointBackendType(opts.CheckpointBackend); err != nil {
					cmd.SilenceUsage = true
					return err
				}
			}

